use fixture_child_orphan_reconciliation::{reconcile,Child,State}; #[test] fn fences_old_generation(){assert_eq!(reconcile(2,Child{generation:2,state:State::Running},None),State::Running);assert_eq!(reconcile(2,Child{generation:1,state:State::Running},Some(State::Succeeded)),State::Succeeded);assert_eq!(reconcile(2,Child{generation:1,state:State::Running},Some(State::Failed)),State::Failed);assert_eq!(reconcile(2,Child{generation:1,state:State::Running},None),State::Orphaned);}
